// Check if this is a valid S3 put event
if (!msg.payload.Records || !msg.payload.Records[0]) {
    return null;
}

// Extract details
const s3 = msg.payload.Records[0].s3;
const objectKey = decodeURIComponent(s3.object.key.replace(/\+/g, " "));
const bucketName = s3.bucket.name;

// 1. The S3 node looks specifically for 'msg.bucket'
msg.bucket = bucketName;

// 2. The S3 node looks specifically for 'msg.filename'
msg.filename = objectKey;
msg.fileId = objectKey.split("/")[1];
msg.fileExt = objectKey.split("/")[2];

// Cleanup: remove the huge raw event payload to keep memory clean
// (Optional, but good practice)
delete msg.payload;

return msg;

// 'NodeClam' and 'Stream' are injected via the Setup tab.

const clamscanConfig = {
    clamdscan: {
        host: 'clamav',
        port: 3310,
        timeout: 60000,
        socket: null,
    },
    preference: 'clamdscan'
};

// Initialize the scanner
const ClamScan = new NodeClam().init(clamscanConfig);

return (async () => {
    try {
        // Capture Start Time
        const startTime = Date.now();

        // Create the stream using the injected 'Stream' variable
        const bufferStream = new Stream.PassThrough();
        bufferStream.end(msg.payload);

        // Measure File Size (msg.payload is a Buffer)
        const bytes = msg.payload.length;
        let readableSize = "";
        let sizeInMB = 0;

        if (bytes < 1024) {
            readableSize = bytes + " Bytes";
            sizeInMB = (bytes / (1024 * 1024)); // Keep raw float for ThingsBoard
        } else if (bytes < 1048576) {
            readableSize = (bytes / 1024).toFixed(2) + " KB";
            sizeInMB = (bytes / (1024 * 1024));
        } else {
            readableSize = (bytes / (1024 * 1024)).toFixed(2) + " MB";
            sizeInMB = (bytes / (1024 * 1024));
        }

        // Perform the scan
        const { isInfected, viruses } = await ClamScan.then(scanner => scanner.scanStream(bufferStream));

        // Calculate Duration
        const scanDuration = Date.now() - startTime;

        // Extract Extension (Robust method)
        // Assumes filename is "userid/fileid/name.ext" or just "name.ext"
        const parts = msg.filename.split('/');
        const realName = parts[parts.length - 1].split('.')[0]; // Get the last part
        const fileExt = parts[parts.length - 1].split('.')[1] || 'unknown';

        msg.headers = msg.headers || {};

        if (isInfected) {
            msg.bucketName = "rejected";
            msg.objectName = msg.filename;
            msg.sourceObject = msg.bucket + "/" + msg.filename;

            // Construct this for web app
            msg.webapp = {
                fileId: msg.fileId,
                status: "rejected",
                scanResults: viruses
            }
            // Construct this for thingsboard
            msg.thingsboard = {
                // filename: msg.fileExt,
                filename: realName,
                file_type: fileExt,
                file_size_mb: Number(sizeInMB.toFixed(4)),
                display_size: readableSize,
                scan_duration_ms: scanDuration,
                status: "INFECTED",
                viruses,
                infected_count: isInfected ? 1 : 0,
                total_scanned: 1
            }

        } else {
            msg.bucketName = "approved";
            msg.objectName = msg.filename;
            msg.sourceObject = msg.bucket + "/" + msg.filename;

            // Construct this for web app
            msg.webapp = {
                fileId: msg.fileId,
                status: "approved",
                scanResults: viruses
            }
            // Construct this for thingsboard
            msg.thingsboard = {
                filename: realName,
                file_type: fileExt,
                file_size_mb: Number(sizeInMB.toFixed(4)),
                display_size: readableSize,
                scan_duration_ms: scanDuration,
                status: "CLEAN",
                viruses,
                infected_count: isInfected ? 1 : 0,
                total_scanned: 1
            }
        }

        msg.scanStatus = isInfected ? "INFECTED" : "CLEAN";
        msg.isInfected = isInfected;
        msg.viruses = viruses;

        return msg;

    } catch (err) {
        node.error("ClamAV Scan Error: " + err.message);
        msg.payload = { error: err.message };
        return [null, msg];
    }
})();
